"""Bash execution wrappers generated for B: ``run_job.sh`` and ``launch.sh``."""

from __future__ import annotations

from solouvm.gen.shell import check_no_newlines

__all__ = ["LAUNCH_SH", "RUN_JOB_SH", "render_launch", "render_run_job"]

RUN_JOB_SH = r"""#!/usr/bin/env bash
# generated by solouvm __SOLOUVM_VERSION__ -- do not edit
set -u

GENERATOR_VERSION="__SOLOUVM_VERSION__"

kind=""
dir=""
log=""
run_id=""
job_id=""
try_n="1"
timeout_s=""
hang_s=""
lock=0
setup_cmd=""
pre_cmd=""
post_cmd=""
mem_limit=""
env_items=()

while [ $# -gt 0 ]; do
    case "$1" in
        --kind)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            kind="$2"; shift 2 ;;
        --dir)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            dir="$2"; shift 2 ;;
        --log)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            log="$2"; shift 2 ;;
        --run-id)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            run_id="$2"; shift 2 ;;
        --job-id)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            job_id="$2"; shift 2 ;;
        --try)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            try_n="$2"; shift 2 ;;
        --timeout)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            timeout_s="$2"; shift 2 ;;
        --hang)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            hang_s="$2"; shift 2 ;;
        --lock)
            lock=1; shift ;;
        --setup)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            setup_cmd="$2"; shift 2 ;;
        --pre)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            pre_cmd="$2"; shift 2 ;;
        --post)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            post_cmd="$2"; shift 2 ;;
        --env)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            env_items+=("$2"); shift 2 ;;
        --mem-limit)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            mem_limit="$2"; shift 2 ;;
        --)
            shift
            break ;;
        *)
            echo "solouvm: error: unknown option $1" >&2
            exit 2 ;;
    esac
done

if [ $# -eq 0 ]; then
    echo "solouvm: error: missing command after --" >&2
    exit 2
fi
cmd=("$@")

case "$kind" in
    build|job|check) ;;
    *)
        echo "solouvm: error: invalid --kind '$kind' (expected build, job, or check)" >&2
        exit 2 ;;
esac

if [ -z "$dir" ]; then
    echo "solouvm: error: missing --dir" >&2
    exit 2
fi

if [ -z "$log" ]; then
    case "$kind" in
        build) log="build.log" ;;
        check) log="check.log" ;;
        *)     log="sim.log" ;;
    esac
fi

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
case "$script_dir" in
    */.solouvm/gen/bin)
        SOLOUVM_ROOT="$(cd "$script_dir/../../.." && pwd -P)"
        ;;
    *)
        SOLOUVM_ROOT="$(pwd -P)"
        ;;
esac
export SOLOUVM_ROOT

if ! mkdir -p "$dir" 2>/dev/null; then
    echo "solouvm: error: cannot create $dir" >&2
    exit 2
fi
abs_dir="$(cd "$dir" 2>/dev/null && pwd -P)" || {
    echo "solouvm: error: cannot create $dir" >&2
    exit 2
}
export SOLOUVM_OUTDIR="$abs_dir"

if [ "$kind" = "job" ]; then
    cmd+=("+SOLOUVM_ROOT=$SOLOUVM_ROOT" "+SOLOUVM_OUTDIR=$abs_dir")
fi

case "$log" in
    /*) log_path="$log" ;;
    *)  log_path="$abs_dir/$log" ;;
esac
facts_path="$abs_dir/job.facts"

timeout_impl=""
timeout_bin=""
forced_impl="${SOLOUVM_TIMEOUT_IMPL:-}"
if [ -n "$forced_impl" ]; then
    case "$forced_impl" in
        timeout)
            timeout_bin=$(command -v timeout 2>/dev/null || true)
            if [ -z "$timeout_bin" ]; then
                echo "solouvm: error: SOLOUVM_TIMEOUT_IMPL=timeout: timeout not found" >&2
                exit 2
            fi
            timeout_impl="timeout"
            ;;
        gtimeout)
            timeout_bin=$(command -v gtimeout 2>/dev/null || true)
            if [ -z "$timeout_bin" ]; then
                echo "solouvm: error: SOLOUVM_TIMEOUT_IMPL=gtimeout: gtimeout not found" >&2
                exit 2
            fi
            timeout_impl="gtimeout"
            ;;
        builtin)
            timeout_impl="builtin"
            ;;
        *)
            echo "solouvm: error: invalid SOLOUVM_TIMEOUT_IMPL '$forced_impl'" >&2
            exit 2
            ;;
    esac
else
    if timeout_bin=$(command -v timeout 2>/dev/null); then
        timeout_impl="timeout"
    elif timeout_bin=$(command -v gtimeout 2>/dev/null); then
        timeout_impl="gtimeout"
    else
        timeout_impl="builtin"
    fi
fi

host=$(hostname -s 2>/dev/null || hostname 2>/dev/null || echo unknown)
lock_dir="${abs_dir}.lock"
lock_held=0
tmp_dir=""
child_pid=""
timeout_wd_pid=""
hang_wd_pid=""
facts_started=0
interrupted=0
start_epoch=0

iso_now() {
    local stamp offset base
    stamp=$(date +%Y-%m-%dT%H:%M:%S%z)
    offset="${stamp#"${stamp%?????}"}"
    base="${stamp%?????}"
    case "$offset" in
        [+-][0-9][0-9][0-9][0-9])
            printf '%s%s:%s\n' "$base" "${offset%??}" "${offset#???}"
            ;;
        *)
            printf '%s%s\n' "$base" "$offset"
            ;;
    esac
}

epoch_now() {
    if [ -n "${EPOCHREALTIME:-}" ]; then
        printf '%s\n' "${EPOCHREALTIME/,/.}"
    else
        local ns
        ns=$(date +%s%N 2>/dev/null || true)
        case "$ns" in
            *[!0-9]*|"") date +%s ;;
            *) LC_ALL=C awk "BEGIN { printf \"%.6f\\n\", $ns / 1000000000 }" ;;
        esac
    fi
}

expand_env_value() {
    local rest="$1" out="" name=""
    while [ -n "$rest" ]; do
        if [[ "$rest" == *'$'* ]]; then
            out+="${rest%%\$*}"
            rest="${rest#*\$}"
            if [[ "$rest" =~ ^\{([A-Za-z_][A-Za-z0-9_]*)\}(.*)$ ]]; then
                name="${BASH_REMATCH[1]}"
                rest="${BASH_REMATCH[2]}"
                if [ "${!name+set}" = "set" ]; then
                    out+="${!name}"
                fi
            elif [[ "$rest" =~ ^([A-Za-z_][A-Za-z0-9_]*)(.*)$ ]]; then
                name="${BASH_REMATCH[1]}"
                rest="${BASH_REMATCH[2]}"
                if [ "${!name+set}" = "set" ]; then
                    out+="${!name}"
                fi
            else
                out+='$'
            fi
        else
            out+="$rest"
            break
        fi
    done
    printf '%s' "$out"
}

stop_watchdogs() {
    if [ -n "${timeout_wd_pid:-}" ]; then
        kill -KILL -"$timeout_wd_pid" 2>/dev/null || true
        wait "$timeout_wd_pid" 2>/dev/null || true
        timeout_wd_pid=""
    fi
    if [ -n "${hang_wd_pid:-}" ]; then
        kill -KILL -"$hang_wd_pid" 2>/dev/null || true
        wait "$hang_wd_pid" 2>/dev/null || true
        hang_wd_pid=""
    fi
}

cleanup_resources() {
    stop_watchdogs
    if [ -n "${tmp_dir:-}" ] && [ -d "$tmp_dir" ]; then
        rm -rf "$tmp_dir" 2>/dev/null || true
    fi
    if [ "${lock_held:-0}" -eq 1 ]; then
        rm -rf "$lock_dir" 2>/dev/null || true
        lock_held=0
    fi
}

on_signal() {
    trap '' TERM INT
    if [ "$interrupted" -eq 1 ]; then
        exit 130
    fi
    interrupted=1
    stop_watchdogs
    if [ -n "${child_pid:-}" ]; then
        kill -TERM -"$child_pid" 2>/dev/null || true
        local grace=0
        while [ "$grace" -lt 10 ] && kill -0 "$child_pid" 2>/dev/null; do
            sleep 0.1
            grace=$((grace + 1))
        done
        if kill -0 "$child_pid" 2>/dev/null; then
            kill -KILL -"$child_pid" 2>/dev/null || true
        fi
        wait "$child_pid" 2>/dev/null || true
        child_pid=""
    fi
    if [ "$facts_started" -eq 1 ]; then
        local end_ep fin_at dur
        end_ep=$(epoch_now)
        fin_at=$(iso_now)
        dur=$(LC_ALL=C awk \
            "BEGIN { d = $end_ep - $start_epoch; if (d < 0) d = 0; printf \"%.3f\", d }")
        {
            printf 'state=interrupted\n'
            printf 'rc=130\n'
            printf 'signal=\n'
            printf 'timed_out=0\n'
            printf 'hung=0\n'
            printf 'finished_at=%s\n' "$fin_at"
            printf 'duration_s=%s\n' "$dur"
        } >> "$facts_path"
    fi
    exit 130
}

trap 'on_signal' TERM INT
trap 'cleanup_resources' EXIT

if [ "$lock" -eq 1 ]; then
    lock_start=$(date +%s)
    while ! mkdir "$lock_dir" 2>/dev/null; do
        owner_file="$lock_dir/owner"
        if [ ! -f "$owner_file" ]; then
            sleep 0.1
        fi
        if [ -f "$owner_file" ]; then
            owner_host=""
            owner_pid=""
            read -r owner_host owner_pid _ < "$owner_file" 2>/dev/null || true
            if [ -n "$owner_host" ] && [ "$owner_host" = "$host" ] \
                && [ -n "$owner_pid" ] && [[ "$owner_pid" =~ ^[0-9]+$ ]] \
                && ! kill -0 "$owner_pid" 2>/dev/null; then
                stale_dir="${lock_dir}.stale.$$"
                if mv "$lock_dir" "$stale_dir" 2>/dev/null; then
                    rm -rf "$stale_dir" 2>/dev/null || true
                    continue
                fi
            fi
        fi
        if [ -n "$timeout_s" ]; then
            now_s=$(date +%s)
            if LC_ALL=C awk "BEGIN {exit !(($now_s - $lock_start) >= $timeout_s)}"; then
                echo "solouvm: error: lock timeout on $lock_dir; run 'solouvm clean --locks'" >&2
                exit 2
            fi
        fi
        sleep 1
    done
    lock_held=1
    printf '%s %s %s\n' "$host" "$$" "$run_id" > "$lock_dir/owner"
    if [ "$kind" = "build" ] && [ -f "$abs_dir/.ok" ]; then
        exit 0
    fi
fi

if [ "$kind" = "build" ]; then
    rm -f "$abs_dir/.ok"
fi

started_at=$(iso_now)
start_epoch=$(epoch_now)

{
    printf 'schema=1\n'
    printf 'generator=solouvm %s\n' "$GENERATOR_VERSION"
    printf 'kind=%s\n' "$kind"
    printf 'run_id=%s\n' "$run_id"
    printf 'job_id=%s\n' "$job_id"
    printf 'try=%s\n' "$try_n"
    printf 'host=%s\n' "$host"
    printf 'pid=%s\n' "$$"
    printf 'timeout_impl=%s\n' "$timeout_impl"
    printf 'started_at=%s\n' "$started_at"
    printf 'state=running\n'
} > "$facts_path"
facts_started=1

cd "$abs_dir" || {
    echo "solouvm: error: cannot enter $abs_dir" >&2
    exit 2
}

: > "$log_path"

hook_rc=0
if [ -n "$setup_cmd" ]; then
    eval "$setup_cmd" >>"$log_path" 2>&1 || hook_rc=$?
fi

if [ "$hook_rc" -eq 0 ] && [ "${#env_items[@]}" -gt 0 ]; then
    for kv in "${env_items[@]}"; do
        env_key="${kv%%=*}"
        env_raw="${kv#*=}"
        env_val=$(expand_env_value "$env_raw")
        export "$env_key=$env_val"
    done
fi

if [ "$hook_rc" -eq 0 ] && [ -n "$pre_cmd" ]; then
    eval "$pre_cmd" >>"$log_path" 2>&1 || hook_rc=$?
fi

rc=0
timed_out=0
hung=0
signal_name=""

if [ "$hook_rc" -ne 0 ]; then
    rc="$hook_rc"
else
    if [ -n "$mem_limit" ]; then
        mem_kb=$(LC_ALL=C awk -v v="$mem_limit" 'BEGIN {
            s = toupper(v);
            if (match(s, /^[0-9]+(\.[0-9]+)?/)) {
                num = substr(s, RSTART, RLENGTH) + 0;
                unit = substr(s, RLENGTH + 1);
                if (unit == "" || unit == "K" || unit == "KB") mul = 1;
                else if (unit == "M" || unit == "MB") mul = 1024;
                else if (unit == "G" || unit == "GB") mul = 1048576;
                else mul = 0;
                if (mul > 0) printf "%.0f", num * mul;
            }
        }')
        if [ -n "$mem_kb" ]; then
            mem_wrap='ulimit -v "$1" 2>/dev/null || true; shift; exec "$@"'
            cmd=("bash" "-c" "$mem_wrap" "_" "$mem_kb" "${cmd[@]}")
        fi
    fi

    tmp_dir=$(mktemp -d "${TMPDIR:-/tmp}/solouvm_job.XXXXXX")
    timeout_flag="$tmp_dir/timed_out"
    hang_flag="$tmp_dir/hung"

    timeout_active=0
    if [ -n "$timeout_s" ] && LC_ALL=C awk "BEGIN {exit !($timeout_s > 0)}"; then
        timeout_active=1
    fi

    if [ "$timeout_active" -eq 1 ] && [ "$timeout_impl" != "builtin" ]; then
        set -m
        "$timeout_bin" --kill-after=10s "$timeout_s" "${cmd[@]}" >>"$log_path" 2>&1 &
        child_pid=$!
        set +m
    else
        set -m
        "${cmd[@]}" >>"$log_path" 2>&1 &
        child_pid=$!
        set +m
    fi

    if [ "$timeout_active" -eq 1 ] && [ "$timeout_impl" = "builtin" ]; then
        set -m
        (
            sleep "$timeout_s"
            if kill -0 "$child_pid" 2>/dev/null; then
                : > "$timeout_flag"
                kill -TERM -"$child_pid" 2>/dev/null || true
                grace=0
                while [ "$grace" -lt 20 ] && kill -0 "$child_pid" 2>/dev/null; do
                    sleep 0.5
                    grace=$((grace + 1))
                done
                if kill -0 "$child_pid" 2>/dev/null; then
                    kill -KILL -"$child_pid" 2>/dev/null || true
                fi
            fi
        ) </dev/null >/dev/null 2>&1 &
        timeout_wd_pid=$!
        set +m
    fi

    if [ -n "$hang_s" ] && LC_ALL=C awk "BEGIN {exit !($hang_s > 0)}"; then
        last_size=$(wc -c < "$log_path" 2>/dev/null || echo 0)
        last_size="${last_size//[[:space:]]/}"
        hang_ms=$(LC_ALL=C awk "BEGIN { printf \"%.0f\", $hang_s * 1000 }")
        set -m
        (
            idle_ms=0
            while kill -0 "$child_pid" 2>/dev/null; do
                sleep 0.5
                if ! kill -0 "$child_pid" 2>/dev/null; then
                    exit 0
                fi
                cur_size=$(wc -c < "$log_path" 2>/dev/null || echo 0)
                cur_size="${cur_size//[[:space:]]/}"
                if [ "$cur_size" != "$last_size" ]; then
                    last_size="$cur_size"
                    idle_ms=0
                else
                    idle_ms=$((idle_ms + 500))
                fi
                if [ "$idle_ms" -ge "$hang_ms" ]; then
                    : > "$hang_flag"
                    kill -TERM -"$child_pid" 2>/dev/null || true
                    grace=0
                    while [ "$grace" -lt 20 ] && kill -0 "$child_pid" 2>/dev/null; do
                        sleep 0.5
                        grace=$((grace + 1))
                    done
                    if kill -0 "$child_pid" 2>/dev/null; then
                        kill -KILL -"$child_pid" 2>/dev/null || true
                    fi
                    exit 0
                fi
            done
        ) </dev/null >/dev/null 2>&1 &
        hang_wd_pid=$!
        set +m
    fi

    wait "$child_pid" || rc=$?
    child_pid=""
    stop_watchdogs

    if [ -f "$hang_flag" ]; then
        hung=1
    elif [ -f "$timeout_flag" ]; then
        timed_out=1
    elif [ "$timeout_active" -eq 1 ] && [ "$timeout_impl" != "builtin" ]; then
        if [ "$rc" -eq 124 ]; then
            timed_out=1
        elif [ "$rc" -eq 137 ]; then
            now_ep=$(epoch_now)
            if LC_ALL=C awk "BEGIN {exit !(($now_ep - $start_epoch) >= $timeout_s)}"; then
                timed_out=1
            fi
        fi
    fi

    if [ "$timed_out" -eq 0 ] && [ "$hung" -eq 0 ] && [ "$rc" -gt 128 ]; then
        sig_num=$((rc - 128))
        if [ "$sig_num" -ge 1 ] && [ "$sig_num" -le 64 ]; then
            raw_sig=$(kill -l "$sig_num" 2>/dev/null || true)
            if [ -n "$raw_sig" ]; then
                signal_name="SIG${raw_sig#SIG}"
            fi
        fi
    fi
fi

if [ -n "$post_cmd" ]; then
    eval "$post_cmd" >>"$log_path" 2>&1 || true
fi

end_epoch=$(epoch_now)
finished_at=$(iso_now)
duration_s=$(LC_ALL=C awk \
    "BEGIN { d = $end_epoch - $start_epoch; if (d < 0) d = 0; printf \"%.3f\", d }")

{
    printf 'state=done\n'
    printf 'rc=%s\n' "$rc"
    printf 'signal=%s\n' "$signal_name"
    printf 'timed_out=%s\n' "$timed_out"
    printf 'hung=%s\n' "$hung"
    printf 'finished_at=%s\n' "$finished_at"
    printf 'duration_s=%s\n' "$duration_s"
} >> "$facts_path"

if [ "$kind" = "build" ] && [ "$rc" -eq 0 ]; then
    : > "$abs_dir/.ok"
fi

if [ "$kind" = "job" ]; then
    exit 0
fi
exit "$rc"
"""

LAUNCH_SH = r"""#!/usr/bin/env bash
# generated by solouvm __SOLOUVM_VERSION__ -- do not edit
set -u

run_id=""
detach=0
budget_s=""

while [ $# -gt 0 ]; do
    case "$1" in
        --run-id)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            run_id="$2"; shift 2 ;;
        --budget)
            if [ $# -lt 2 ]; then
                echo "solouvm: error: option $1 requires an argument" >&2
                exit 2
            fi
            budget_s="$2"; shift 2 ;;
        --detach)
            detach=1; shift ;;
        --)
            shift
            break ;;
        *)
            echo "solouvm: error: unknown option $1" >&2
            exit 2 ;;
    esac
done

if [ -z "$run_id" ]; then
    echo "solouvm: error: missing --run-id" >&2
    exit 2
fi
if [ $# -eq 0 ]; then
    echo "solouvm: error: missing command after --" >&2
    exit 2
fi

cmd=("$@")

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
case "$script_dir" in
    */.solouvm/gen/bin)
        SOLOUVM_ROOT="$(cd "$script_dir/../../.." && pwd -P)"
        ;;
    *)
        SOLOUVM_ROOT="$(pwd -P)"
        ;;
esac
export SOLOUVM_ROOT

run_dir="$SOLOUVM_ROOT/.solouvm/runs/$run_id"
if ! mkdir -p "$run_dir" 2>/dev/null; then
    echo "solouvm: error: cannot create $run_dir" >&2
    exit 2
fi

host=$(hostname -s 2>/dev/null || hostname 2>/dev/null || echo unknown)
pid_file="$run_dir/launch.pid"
log_file="$run_dir/launch.log"

if [ "$detach" -eq 1 ]; then
    set -m
    nohup "${cmd[@]}" </dev/null >"$log_file" 2>&1 &
    pgid=$!
    set +m
    printf '%s %s\n' "$host" "$pgid" > "$pid_file"
    if [ -n "$budget_s" ] && LC_ALL=C awk "BEGIN {exit !($budget_s > 0)}"; then
        nohup bash -c '
            sleep "$1"
            pgid="$2"
            if kill -0 -"$pgid" 2>/dev/null; then
                kill -TERM -"$pgid" 2>/dev/null || true
                grace=0
                while [ "$grace" -lt 10 ] && kill -0 -"$pgid" 2>/dev/null; do
                    sleep 0.5
                    grace=$((grace + 1))
                done
                if kill -0 -"$pgid" 2>/dev/null; then
                    kill -KILL -"$pgid" 2>/dev/null || true
                fi
            fi
        ' _ "$budget_s" "$pgid" </dev/null >/dev/null 2>&1 &
    fi
    exit 0
fi

pgid=""
on_signal() {
    trap '' TERM INT
    if [ -n "${pgid:-}" ]; then
        kill -TERM -"$pgid" 2>/dev/null || true
        wait "$pgid" 2>/dev/null || true
    fi
    exit 130
}
trap 'on_signal' TERM INT

set -m
"${cmd[@]}" >"$log_file" 2>&1 &
pgid=$!
set +m

printf '%s %s\n' "$host" "$pgid" > "$pid_file"

rc=0
wait "$pgid" || rc=$?
exit "$rc"
"""


def render_run_job(version: str = "0.1.0") -> str:
    """Render ``run_job.sh`` with ``version`` embedded in the header and ``generator=`` line."""
    check_no_newlines(version, field="version")
    return RUN_JOB_SH.replace("__SOLOUVM_VERSION__", version)


def render_launch(version: str = "0.1.0") -> str:
    """Render ``launch.sh`` with ``version`` embedded in the header."""
    check_no_newlines(version, field="version")
    return LAUNCH_SH.replace("__SOLOUVM_VERSION__", version)
